CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blogs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, heading TEXT, subheading TEXT, content TEXT NOT NULL, author TEXT NOT NULL, category TEXT, tags JSONB NOT NULL DEFAULT '[]'::jsonb, image_link TEXT, video_link TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS contacts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT NOT NULL, phone_number TEXT NOT NULL, business_category TEXT NOT NULL, company_name TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS portal_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), phone_number TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL DEFAULT '', role TEXT NOT NULL CHECK (role IN ('student','admin')), password_hash TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, date_joined TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS student_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL UNIQUE REFERENCES portal_users(id) ON DELETE CASCADE, college_name TEXT NOT NULL DEFAULT '', course_name TEXT NOT NULL DEFAULT '', branch TEXT NOT NULL DEFAULT '', year TEXT NOT NULL DEFAULT '', enrollment_type TEXT NOT NULL DEFAULT 'course' CHECK (enrollment_type IN ('course','internship')), photo_key TEXT, photo_name TEXT);
CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_id UUID NOT NULL REFERENCES student_profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', tech_stack TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'planned' CHECK (status IN ('completed','in_progress','planned')), link TEXT NOT NULL DEFAULT '', assigned_by UUID REFERENCES portal_users(id) ON DELETE SET NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certificates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), student_id UUID NOT NULL REFERENCES student_profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, issuer TEXT NOT NULL DEFAULT '', issue_date TEXT, credential_id TEXT NOT NULL DEFAULT '', assigned_by UUID REFERENCES portal_users(id) ON DELETE SET NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS project_files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES student_profiles(id) ON DELETE CASCADE, file_name TEXT NOT NULL, mimetype TEXT, data BYTEA NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certificate_files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certificate_id UUID NOT NULL REFERENCES certificates(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES student_profiles(id) ON DELETE CASCADE, file_name TEXT NOT NULL, mimetype TEXT, data BYTEA NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS captchas (id TEXT PRIMARY KEY, answer TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS stored_files (key TEXT PRIMARY KEY, data BYTEA NOT NULL, mimetype TEXT);
